namespace sv_9e930b11217d4312ad5310c684511a35.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<string> _pool =
    [
        "Deployment to production completed successfully.",
        "New comment on pull request #42.",
        "Build failed for branch 'feature/login'.",
        "Your subscription renews tomorrow.",
        "Server CPU usage exceeded 90%.",
        "New team member joined the project.",
        "Security patch available for dependency X.",
        "Scheduled maintenance window starts at midnight.",
        "Code review requested by @alice.",
        "Database backup completed."
    ];

    /// <summary>Returns the initial batch of notifications.</summary>
    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var items = _pool.Take(4).Select(m => new NotificationItem
        {
            Id = _nextId++,
            Message = m,
            Timestamp = DateTime.UtcNow.AddMinutes(-Random.Shared.Next(1, 60))
        }).ToList();

        return Task.FromResult(items);
    }

    /// <summary>Simulates polling — randomly returns 0-1 new notifications.</summary>
    public Task<List<NotificationItem>> CheckForNewAsync()
    {
        var result = new List<NotificationItem>();

        if (Random.Shared.Next(0, 3) == 0) // ~33 % chance each poll
        {
            var msg = _pool[Random.Shared.Next(_pool.Count)];
            result.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = msg,
                Timestamp = DateTime.UtcNow
            });
        }

        return Task.FromResult(result);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@using sv_9e930b11217d4312ad5310c684511a35.Services
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading…</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Items.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<NotificationItem>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when the value wasn't restored from prerender state.
        Items ??= await NotificationSvc.GetInitialNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender, so this is safe.
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newItems = await NotificationSvc.CheckForNewAsync();
            if (newItems.Count > 0)
            {
                Items!.AddRange(newItems);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

